+		it('groups non-colliding keys before falling back', () => {
+			expect(
+				toSearchObject([['FROM', 'a@example.com'], 'UNSEEN', ['FROM', 'b@example.com']]),
+			).toEqual({
+				not: {
+					or: [{ not: { from: 'a@example.com', seen: false } }, { not: { from: 'b@example.com' } }],
+				},
+			});
