+export async function getGoogleAccessToken(
+	this: GoogleAccessTokenContext,
+	credentials: IDataObject,
+	service: GoogleServiceAccount,
+): Promise<IDataObject> {
+	credentials.email = ((credentials.email as string) || '').trim();
+
+	return await requestGoogleAccessToken.call(
+		this,
+		credentials,
+		googleServiceAccountScopes[service],
+		(credentials.delegatedEmail as string) || credentials.email,
+	);
+}
+
+function parseCredentialScopes(scopes: unknown): string[] {
+	if (typeof scopes !== 'string') return [];
+	return scopes
+		.replace(/\\n/g, '\n')
+		.split(/[,\s\n]+/)
+		.filter((scope) => scope);
+}
+
+/**
+ * Requests an access token to validate a Google Service Account credential.
+ *
+ * With domain-wide delegation, Google only issues a token for the impersonated user if every
+ * requested scope was authorized for the service account in the Workspace Admin console;
+ * otherwise it answers `unauthorized_client`. The credential is shared by all Google nodes, so
+ * the scopes of whichever node provides the test (e.g. Sheets) are usually not the ones the
+ * admin authorized (e.g. Gmail). Impersonation is therefore only verified when the user listed
+ * the scopes explicitly (HTTP Request node setup); otherwise the service account and private
+ * key are verified without impersonating, and delegation is checked when a node uses its scopes.
+ */
+export async function getGoogleCredentialTestAccessToken(
+	this: ICredentialTestFunctions,
+	credentials: IDataObject,
+	service: GoogleServiceAccount,
+): Promise<IDataObject> {
+	const email = ((credentials.email as string) || '').trim();
+	const credentialsToTest = { ...credentials, email };
+	const delegatedEmail = ((credentials.delegatedEmail as string) || '').trim();
+	const configuredScopes = credentials.httpNode ? parseCredentialScopes(credentials.scopes) : [];
+
+	if (delegatedEmail && configuredScopes.length) {
+		return await requestGoogleAccessToken.call(
+			this,
+			credentialsToTest,
+			configuredScopes,
+			delegatedEmail,
+		);
+	}
+
+	return await requestGoogleAccessToken.call(
+		this,
+		credentialsToTest,
+		googleServiceAccountScopes[service],
+		email,
+	);
+}
