+	return { default: { sign }, sign };
+});
+
+describe('getGoogleCredentialTestAccessToken', () => {
+	const mockedSign = jwt.sign as unknown as Mock;
+	const serviceAccount = 'svc@project.iam.gserviceaccount.com';
+	const privateKey = '-----BEGIN PRIVATE KEY-----\nkey\n-----END PRIVATE KEY-----';
+
+	const signedPayload = () => mockedSign.mock.calls[0][0] as { sub: string; scope: string };
+
+	let ctx: ICredentialTestFunctions;
+	let request: Mock;
+
+	beforeEach(() => {
+		mockedSign.mockClear();
+		ctx = mock<ICredentialTestFunctions>();
+		request = vi.fn().mockResolvedValue({ access_token: 'token' });
+		ctx.helpers = { request } as any;
+	});
+
+	it('does not impersonate with node scopes the admin may not have delegated', async () => {
+		// Domain-wide delegation granted only for Gmail; the Sheets scopes used by the test would be
+		// rejected by Google with `unauthorized_client` for the impersonated user.
+		const credentials: IDataObject = {
+			email: ` ${serviceAccount} `,
+			privateKey,
+			inpersonate: true,
+			delegatedEmail: 'user@workspace.com',
+		};
+
+		const result = await getGoogleCredentialTestAccessToken.call(ctx, credentials, 'sheetV2');
+
+		expect(result).toEqual({ access_token: 'token' });
+		expect(signedPayload()).toMatchObject({
+			iss: serviceAccount,
+			sub: serviceAccount,
+			scope: googleServiceAccountScopes.sheetV2.join(' '),
+		});
+		expect(request).toHaveBeenCalledWith(
+			expect.objectContaining({
+				uri: 'https://oauth2.googleapis.com/token',
+				form: expect.objectContaining({ assertion: 'signed-jwt' }),
+			}),
+		);
+		expect(credentials.email).toBe(` ${serviceAccount} `);
+	});
+
+	it('impersonates with the scopes the user configured for the HTTP Request node', async () => {
+		const credentials: IDataObject = {
+			email: serviceAccount,
+			privateKey,
+			inpersonate: true,
+			delegatedEmail: 'user@workspace.com',
+			httpNode: true,
+			scopes: 'https://mail.google.com/,\nhttps://www.googleapis.com/auth/gmail.modify',
+		};
+
+		await getGoogleCredentialTestAccessToken.call(ctx, credentials, 'sheetV2');
+
+		expect(signedPayload()).toMatchObject({
+			iss: serviceAccount,
+			sub: 'user@workspace.com',
+			scope: 'https://mail.google.com/ https://www.googleapis.com/auth/gmail.modify',
+		});
+	});
+
+	it('uses the node scopes for the service account when not impersonating', async () => {
+		const credentials: IDataObject = { email: serviceAccount, privateKey };
+
+		await getGoogleCredentialTestAccessToken.call(ctx, credentials, 'chat');
