+/**
+ * Telegram parses rich message Markdown as CommonMark, where a single newline
+ * is a soft break rendered as a space. Turn every single newline into a hard
+ * line break (two trailing spaces) so line breaks typed by the user are kept.
+ * Blank lines (paragraph breaks) and fenced code blocks are left untouched.
+ */
+export function preserveMarkdownLineBreaks(markdown: string) {
+	const lines = markdown.split(/\r?\n/);
+	// A backtick fence's info string can't contain backticks, else it's inline code
+	const openFenceRegex = /^ {0,3}(`{3,}(?=[^`]*$)|~{3,})/;
+	const closeFenceRegex = /^ {0,3}(`{3,}|~{3,})\s*$/;
+	let openFence: string | undefined;
+
+	return lines
+		.map((line, index) => {
+			if (openFence !== undefined) {
+				const fence = closeFenceRegex.exec(line)?.[1];
+				if (fence && fence[0] === openFence[0] && fence.length >= openFence.length) {
+					openFence = undefined;
+				}
+				return line;
+			}
+			const fence = openFenceRegex.exec(line)?.[1];
+			if (fence) {
+				openFence = fence;
+				return line;
+			}
+
+			const nextLine = lines[index + 1];
+			const isFollowedByText = nextLine !== undefined && nextLine.trim() !== '';
+			const hasHardBreak = / {2}$/.test(line) || line.endsWith('\\');
+			if (line.trim() === '' || !isFollowedByText || hasHardBreak) {
+				return line;
+			}
+			return `${line}  `;
+		})
+		.join('\n');
+}
