+/**
+ * Whether the text up to the end of `text` is inside a JSON string literal,
+ * given whether it started inside one.
+ */
+function endsInsideJsonString(text: string, startsInsideString: boolean) {
+	let insideString = startsInsideString;
+	for (let i = 0; i < text.length; i++) {
+		const char = text[i];
+		if (insideString && char === '\\') {
+			i++;
+		} else if (char === '"') {
+			insideString = !insideString;
+		}
+	}
+	return insideString;
+}
+
+function isValidJson(value: string) {
+	try {
+		JSON.parse(value);
+		return true;
+	} catch (error) {
+		return false;
+	}
+}
+
+/**
+ * Whether a string is the ISO serialization of a Luxon DateTime, Duration or Interval
+ * that cannot be used as a JSON value as-is (e.g. `2024-01-01T00:00:00.000+00:00`).
+ */
+function isUnquotedLuxonIsoString(value: string) {
+	if (isValidJson(value)) return false;
+
+	return (
+		DateTime.fromISO(value, { setZone: true }).isValid ||
+		Duration.fromISO(value).isValid ||
+		Interval.fromISO(value, { setZone: true }).isValid
+	);
+}
