+ * Interval values are serialized to ISO strings by the VM expression engine, so they
+ * no longer arrive as objects; when such a value is inserted outside a JSON string
+ * literal it is inserted as a JSON string, the same way a Luxon object is serialized.
+ */
+export function resolveResolvables(
+	template: string,
+	evaluate: (resolvable: string) => unknown,
+	options: { json?: boolean } = {},
+) {
+	const resolvableRegex = /({{[\s\S]*?}})/g;
+	let result = '';
+	let lastIndex = 0;
+	let insideString = false;
+
+	for (const match of template.matchAll(resolvableRegex)) {
+		const resolvable = match[1];
+		const literal = template.slice(lastIndex, match.index);
+		result += literal;
+		lastIndex = match.index + resolvable.length;
+
+		if (options.json) insideString = endsInsideJsonString(literal, insideString);
+
+		const resolvedValue = evaluate(resolvable);
+
+		if (typeof resolvedValue === 'object' && resolvedValue !== null) {
+			result += JSON.stringify(resolvedValue);
+		} else if (
+			options.json &&
