+const SPLUNK_RELATIVE_TIME_REGEX = /^(rt)?(now|([+-]\d*[a-z]+|@[a-z]+\d*)+)$/i;
+const UNIX_EPOCH_REGEX = /^\d+(\.\d+)?$/;
