+export function toUnixEpoch(
+	timestamp: unknown,
+	node: INode,
+	field: string,
+	itemIndex: number,
+): number | string {
+	const value = String(timestamp).trim();
+
+	if (SPLUNK_RELATIVE_TIME_REGEX.test(value)) return value;
+
+	// Checked before Date.parse, which reads short numbers such as `0` or `2024` as years
+	if (UNIX_EPOCH_REGEX.test(value)) return Number(value);
