+	const parsed = Date.parse(value);
+	if (Number.isNaN(parsed)) {
+		throw new NodeOperationError(node, `Invalid time value '${value}' for '${field}'`, {
+			itemIndex,
+			description:
+				'Use an absolute date (e.g. 2024-01-01T00:00:00Z), a Unix epoch timestamp or a Splunk relative time modifier (e.g. -15m, -1d@d, now)',
+		});
+	}
+
+	return parsed / 1000;
