+import { Agent } from '../../sdk/agent';
+import { HIGH_REASONING_DEFAULT_MAX_OUTPUT_TOKENS } from '../model/provider-quirks';
+
+/** Anthropic Messages response, the wire format of MiniMax's Anthropic-compatible API. */
+function anthropicMessage(text: string): Response {
+	return new Response(
+		JSON.stringify({
+			id: 'msg_1',
+			type: 'message',
+			role: 'assistant',
+			model: 'MiniMax-M3',
+			content: [{ type: 'text', text }],
+			stop_reason: 'end_turn',
+			stop_sequence: null,
+			usage: { input_tokens: 10, output_tokens: 5 },
+		}),
+		{ status: 200, headers: { 'content-type': 'application/json' } },
+	);
+}
+
+describe('MiniMax output token cap', () => {
+	it('sends a realistic max_tokens instead of the 4096 unknown-model fallback', async () => {
+		const requestBodies: Array<Record<string, unknown>> = [];
+		const fetchFn: typeof fetch = async (_input, init) => {
+			requestBodies.push(JSON.parse(init?.body as string) as Record<string, unknown>);
+			return await Promise.resolve(anthropicMessage('A long incident report.'));
+		};
+
+		const agent = new Agent('minimax-max-tokens')
+			.model({ id: 'minimax/MiniMax-M3', apiKey: 'mm-test', url: 'https://api.minimax.io/v1' })
+			.modelFetch(fetchFn)
+			.instructions('You are a concise assistant.');
+
+		const result = await agent.generate('Write a long incident report.');
+
+		expect(result.finishReason).toBe('stop');
+		expect(requestBodies).toHaveLength(1);
+		expect(requestBodies[0].max_tokens).toBe(HIGH_REASONING_DEFAULT_MAX_OUTPUT_TOKENS);
+	});
+
+	it('still lets an explicit maxOutputTokens win', async () => {
+		const requestBodies: Array<Record<string, unknown>> = [];
+		const fetchFn: typeof fetch = async (_input, init) => {
+			requestBodies.push(JSON.parse(init?.body as string) as Record<string, unknown>);
+			return await Promise.resolve(anthropicMessage('Short.'));
+		};
+
+		const agent = new Agent('minimax-max-tokens-override')
+			.model({ id: 'minimax/MiniMax-M3', apiKey: 'mm-test', url: 'https://api.minimax.io/v1' })
+			.modelFetch(fetchFn)
+			.instructions('You are a concise assistant.');
+
+		await agent.generate('Say hi.', { maxOutputTokens: 1234 });
+
+		expect(requestBodies[0].max_tokens).toBe(1234);
+	});
+});
