+/** A LiteLLM proxy routing to Bedrock: it serves /responses but rejects OpenAI-only fields. */
+function liteLlmEndpoint(stream: boolean) {
+	const bodies: Array<Record<string, unknown>> = [];
+	const fetch = vi.fn<typeof globalThis.fetch>().mockImplementation(async (input, init) => {
+		const url = input instanceof Request ? input.url : String(input);
+		const body = JSON.parse(String(init?.body)) as Record<string, unknown>;
+		bodies.push(body);
+		if (!url.endsWith('/responses')) return new Response('not found', { status: 404 });
+		const unsupported = ['prompt_cache_key', 'prompt_cache_retention'].filter((key) => key in body);
+		if (unsupported.length > 0) {
+			return Response.json(
+				{
+					error: {
+						message: `litellm.UnsupportedParamsError: bedrock does not support parameters: ${JSON.stringify(unsupported)}, for model=eu.anthropic.${MODEL_ID}.`,
+						type: 'invalid_request_error',
+						param: null,
+						code: '400',
+					},
+				},
+				{ status: 400 },
+			);
+		}
+		const response = {
+			id: 'resp_1',
+			object: 'response',
+			created_at: 0,
+			model: MODEL_ID,
+			status: 'completed',
+			output: [
+				{
+					id: 'msg_1',
+					type: 'message',
+					role: 'assistant',
+					status: 'completed',
+					content: [{ type: 'output_text', text: 'from bedrock', annotations: [] }],
+				},
+			],
+			usage: { input_tokens: 10, output_tokens: 5, total_tokens: 15 },
+		};
+		if (!stream) return Response.json(response);
+		const events = [
+			{ type: 'response.created', response: { ...response, status: 'in_progress', output: [] } },
+			{
+				type: 'response.output_item.added',
+				output_index: 0,
+				item: {
+					id: 'msg_1',
+					type: 'message',
+					role: 'assistant',
+					status: 'in_progress',
+					content: [],
+				},
+			},
+			{
+				type: 'response.output_text.delta',
+				item_id: 'msg_1',
+				output_index: 0,
+				content_index: 0,
+				delta: 'from bedrock',
+			},
+			{ type: 'response.output_item.done', output_index: 0, item: response.output[0] },
+			{ type: 'response.completed', response },
+		];
+		return new Response(
+			events.map((event) => `event: ${event.type}\ndata: ${JSON.stringify(event)}\n\n`).join(''),
+			{ headers: { 'content-type': 'text/event-stream' } },
+		);
+	});
+	return { fetch, bodies };
+}
+
+describe.each(['generate', 'stream'] as const)(
+	'OpenAI credentials on a custom endpoint with prompt caching (%s)',
+	(mode) => {
+		it('runs the agent without OpenAI-only prompt cache fields', async () => {
+			const { fetch, bodies } = liteLlmEndpoint(mode === 'stream');
+			const runtime = new AgentRuntime({
+				name: 'test',
+				model: {
+					id: `openai/${MODEL_ID}`,
+					apiKey: 'sk-test',
+					url: 'https://litellm.example.com/v1',
+				},
+				modelFetch: fetch,
+				modelCost: { input: 1, output: 1 },
+				instructions: 'You are a test assistant.',
+				promptCaching: { enabled: true },
+			});
+
+			if (mode === 'generate') {
+				const result = await runtime.generate('hello');
+
+				expect(result.finishReason).toBe('stop');
+			} else {
+				const result = await runtime.stream('hello', { smoothStream: false });
+				const chunks: StreamChunk[] = [];
+
+				for await (const chunk of result.stream) chunks.push(chunk);
+
+				expect(chunks.filter((chunk) => chunk.type === 'error')).toEqual([]);
+				expect(chunks.at(-1)).toMatchObject({ type: 'finish', finishReason: 'stop' });
+			}
+
+			expect(bodies).toHaveLength(1);
+			expect(bodies[0]).toMatchObject({ model: MODEL_ID });
+			expect(bodies[0]).not.toHaveProperty('prompt_cache_key');
+			expect(bodies[0]).not.toHaveProperty('prompt_cache_retention');
+		});
+	},
+);
