+// Compact form for summary tiles: ~4 significant digits (0.7283, 12.35), but
+// whole numbers of 1,000+ keep every integer digit (12,345,678 — never 12,350,000),
+// and at most 6 decimals so float noise (5.5e-17) can't render as a long string.
 function formatMetricNumber(value: number): string {
-	return value.toLocaleString(undefined, { maximumFractionDigits: 6 });
+	return Math.abs(value) >= 1000
+		? value.toLocaleString(undefined, { maximumFractionDigits: 0 })
+		: Number(value.toPrecision(4)).toLocaleString(undefined, { maximumFractionDigits: 6 });
+}
+
+// Full-precision form for hover tooltips, where the compact tile value is rounded.
+function formatMetricExactNumber(value: number): string {
+	return value.toLocaleString(undefined, { maximumFractionDigits: 20 });
+}
+
+/**
+ * Exact value of an unscaled custom metric, for a tooltip — '' when the
+ * compact `formatMetricValue` output already shows every digit, or when the
+ * metric is a score (those keep their percentage formatting).
+ */
+export function formatMetricExactValue(
+	value: number | undefined,
+	options: { key?: string; category?: MetricCategory; scale?: MetricScale } = {},
+): string {
+	const num = normalizeMetricValue(value);
+	if (num === undefined || !isUnscaledCustomMetric(options)) return '';
+	const exact = formatMetricExactNumber(num);
+	return exact === formatMetricNumber(num) ? '' : exact;
 }

