+import { mockDeep } from 'vitest-mock-extended';
+import type { IExecuteFunctions, INodeExecutionData } from 'n8n-workflow';
+
+import { MicrosoftOutlookV1 } from '../../v1/MicrosoftOutlookV1.node';
+
+describe('Microsoft Outlook V1 - messageAttachment:add', () => {
+	it('should read the binary property name for each item', async () => {
+		const node = new MicrosoftOutlookV1({
+			displayName: 'Microsoft Outlook',
+			name: 'microsoftOutlook',
+			group: ['transform'],
+			description: 'Consume Microsoft Outlook API',
+		});
+		const items: INodeExecutionData[] = [
+			{
+				json: { field: 'data' },
+				binary: { data: { data: 'Zmlyc3Q=', mimeType: 'text/plain', fileName: 'first.txt' } },
+			},
+			{
+				json: { field: 'attachment' },
+				binary: {
+					attachment: { data: 'c2Vjb25k', mimeType: 'text/plain', fileName: 'second.txt' },
+				},
+			},
+		];
+		const mockExecuteFunctions = mockDeep<IExecuteFunctions>();
+		mockExecuteFunctions.getInputData.mockReturnValue(items);
+		mockExecuteFunctions.continueOnFail.mockReturnValue(false);
+		mockExecuteFunctions.getNodeParameter.mockImplementation(
+			(name: string, itemIndex: number) => {
+				const params: Record<string, unknown> = {
+					resource: 'messageAttachment',
+					operation: 'add',
+					messageId: `message-${itemIndex}`,
+					binaryPropertyName: items[itemIndex].json.field,
+					additionalFields: {},
+				};
+				return params[name] as never;
+			},
+		);
+		mockExecuteFunctions.helpers.getBinaryDataBuffer.mockResolvedValue(Buffer.from('content'));
+		mockExecuteFunctions.getCredentials.mockResolvedValue({});
+		mockExecuteFunctions.helpers.requestOAuth2.mockResolvedValue({});
+		mockExecuteFunctions.helpers.returnJsonArray.mockImplementation(
+			(data) => data as unknown as INodeExecutionData[],
+		);
+
+		const result = await node.execute.call(mockExecuteFunctions);
+
+		expect(result).toEqual([[{ success: true }, { success: true }]]);
+		expect(mockExecuteFunctions.helpers.getBinaryDataBuffer).toHaveBeenNthCalledWith(1, 0, 'data');
+		expect(mockExecuteFunctions.helpers.getBinaryDataBuffer).toHaveBeenNthCalledWith(
+			2,
+			1,
+			'attachment',
+		);
+		expect(mockExecuteFunctions.helpers.requestOAuth2).toHaveBeenCalledWith(
+			'microsoftOutlookOAuth2Api',
+			expect.objectContaining({
+				method: 'POST',
+				body: expect.objectContaining({ name: 'second.txt', contentBytes: 'c2Vjb25k' }),
+			}),
+		);
+	});
+});
